    data=json.loads(result.read_text()) if result.exists() else {};cert=data.get('certificate',{});summary=data.get('summary',{});obj=summary.get('objective',math.nan)
    passed=run.returncode==0 and cert.get('certified') and cert.get('tolerance')==report['problems'][str(n)]['solver']['tolerance'] and cert.get('continuous_time_within_tolerance') and cert.get('gates') and all(g['passed'] and math.isfinite(g['value']) for g in cert['gates'].values()) and data.get('backend',{}).get('hidden_cpu_fallback') is False and math.isfinite(obj) and abs(obj-references[n])<=1e-8
    report['samples'].append({'intervals':n,'mode':mode,'repeat':repeat,'warmup':repeat<2,'passed':bool(passed),'returncode':run.returncode,'process_seconds':elapsed,'command':cmd,'single_block_test_flag':mode=='single','stdout':run.stdout,'stderr':run.stderr,'result_path':str(result),'result_sha256':hashlib.sha256(result.read_bytes()).hexdigest() if result.exists() else None,**{k:data.get(k) for k in ['status','summary','timings','certificate','backend','independent_replay']}})
    output.write_text(json.dumps(report,indent=2)+'\n')
    print(n,mode,repeat,bool(passed),summary.get('inner_iterations'),flush=True)
report['settings']={}
for n in problems:
 for mode in ['single','multi']:
  rows=[r for r in report['samples'] if r['intervals']==n and r['mode']==mode];measured=[r for r in rows if not r['warmup']];qualified=all(r['passed'] for r in rows)
  times=sorted(r['timings']['scvx_total_seconds'] for r in measured)
  report['settings'][f'{n}:{mode}']={'all_qualified':qualified,'failures':sum(not r['passed'] for r in rows),'median_scvx_seconds':statistics.median(times) if qualified else None,'p95_scvx_seconds_nearest_rank':times[math.ceil(.95*len(times))-1] if qualified else None,'median_inner_iterations':statistics.median(r['summary']['inner_iterations'] for r in measured) if qualified else None}
